//adjustMaxHeight\r\n            vo.adjustMaxHeight()\r\n\r\n        },\r\n\r\n        onPlacementChange: function(placement) {\r\n            let vo = this\r\n            vo.popperPlacement = placement\r\n            vo.adjustMaxHeight()\r\n        },\r\n\r\n        adjustMaxHeight: function() {\r\n            let vo = this\r\n\r\n            //check\r\n            if (!vo.show) {\r\n                return\r\n            }\r\n\r\n            try {\r\n\r\n                //ct\r\n                let ct = vo.$refs.ct\r\n                if (!ct) {\r\n                    return\r\n                }\r\n\r\n                //windowHeight\r\n                let h = window.innerHeight\r\n\r\n                //placement\r\n                let placement = vo.popperPlacement\r\n\r\n                //Popper.js尚未定位完成, 保持初始限制高度\r\n                if (!placement) {\r\n                    return\r\n                }\r\n\r\n                //rt\r\n                let rt = domGetBoudRect(ct)\r\n\r\n                //hc, 實際內容高度\r\n                let hc = ct.scrollHeight\r\n\r\n                //根據方向計算可用空間\r\n                let margin = 30\r\n                let hca\r\n                if (placement.startsWith('top')) {\r\n                    //彈窗在上方, 底部對齊觸發元素往上延伸\r\n                    hca = rt.bottom - margin\r\n                }\r\n                else {\r\n                    //預設彈窗在下方, 頂部對齊觸發元素下方往下延伸\r\n                    hca = h - rt.top - margin\r\n                }\r\n\r\n                //layoutShowScrollYNew\r\n                let layoutShowScrollYNew = hc > hca\r\n\r\n                //layoutMaxHeightNew\r\n                let layoutMaxHeightNew = Math.max(hca, vo.layoutMinHeight)\r\n\r\n                //check, 避免微小的數值抖動導致迴圈\r\n                if (layoutShowScrollYNew === vo.layoutShowScrollY && Math.abs(layoutMaxHeightNew - vo.layoutMaxHeight) < 2) {\r\n                    return\r\n                }\r\n\r\n                //layoutShowScrollY\r\n                vo.layoutShowScrollY = layoutShowScrollYNew\r\n                // console.log('layoutShowScrollY', vo.layoutShowScrollY)\r\n\r\n                //layoutMaxHeight\r\n                vo.layoutMaxHeight = layoutMaxHeightNew\r\n                // console.log('layoutMaxHeight', vo.layoutMaxHeight)\r\n\r\n            }\r\n            catch (err) {}\r\n\r\n        },\r\n\r\n        openEyeDropper: function() {\r\n            // console.log('methods openEyeDropper')\r\n\r\n            let vo = this\r\n\r\n            //check\r\n            if (!vo.hasEyeDropper) {\r\n                return\r\n            }\r\n\r\n            vo.loadingEyeDropper = true\r\n\r\n            let eyeDropper = new window.EyeDropper()\r\n            eyeDropper\r\n                .open()\r\n                .then((res) => {\r\n                    // console.log('res', res)\r\n                    let hex = get(res, 'sRGBHex', '#fff')\r\n                    vo.valueNew = hex\r\n                })\r\n                .catch((err) => {\r\n                    console.log(err)\r\n                })\r\n                .finally(() => {\r\n                    vo.loadingEyeDropper = false\r\n                })\r\n\r\n        },\r\n\r\n        clickColor: function() {\r\n            // console.log('methods clickColor')\r\n\r\n            let vo = this\r\n\r\n            //check, 不可編輯時跳出\r\n            if (!vo.editable) {\r\n                return\r\n            }\r\n\r\n            //emit\r\n            vo.$emit('input', vo.valueNew)\r\n\r\n            //hide\r\n            vo.show = false\r\n\r\n        },\r\n\r\n    },\r\n}\r\n<\/script>\r\n\r\n<style scoped>\r\n.icon-spinner {\r\n    animation: spin-animation 1.5s infinite;\r\n    display: inline-block;\r\n}\r\n@keyframes spin-animation {\r\n    0% {\r\n        transform: rotate(0deg);\r\n    }\r\n    100% {\r\n        transform: rotate(359deg);\r\n    }\r\n}\r\n</style>\r\n"]},media:void 0})},Hm,"data-v-6e25f7a9",0,0,0,Lc);function Vm(e,t,n){return null==e?e:functio